import{_ as t,o as d,c as o,a2 as r}from"./chunks/framework.CDU0sSpB.js";const u=JSON.parse('{"title":"参与贡献","description":"Hearth 的仓库结构、本地运行、写作约定、提交检查和文档事实源。","frontmatter":{"title":"参与贡献","description":"Hearth 的仓库结构、本地运行、写作约定、提交检查和文档事实源。","outline":[2]},"headers":[],"relativePath":"reference/contributing.md","filePath":"reference/contributing.md","lastUpdated":1794305977000}'),c={name:"reference/contributing.md"};function a(i,e,n,s,p,l){return d(),o("div",null,[...e[0]||(e[0]=[r('<h1 id="参与贡献" tabindex="-1">参与贡献 <a class="header-anchor" href="#参与贡献" aria-label="Permalink to &quot;参与贡献&quot;">​</a></h1><p class="lead">Hearth 已进入第一阶段 MVP 实现。最有价值的贡献仍然是澄清边界、挑战风险假设、补充真实任务，以及让实现者更容易读懂文档；现在也欢迎带验收证据的实现改动。改动不需要写得很多，但必须让结论更准确、证据更清楚。</p><h2 id="本地运行与写作约定" tabindex="-1">本地运行与写作约定 <a class="header-anchor" href="#本地运行与写作约定" aria-label="Permalink to &quot;本地运行与写作约定&quot;">​</a></h2><p>正式文档只放在 <code>docs/</code>，站点直接从这些文件构建。README 是仓库入口，不是另一份正文副本。中文是默认阅读路径，英文镜像使用相同路径和结构。</p><table tabindex="0"><thead><tr><th>目录</th><th>内容</th></tr></thead><tbody><tr><td><code>docs/design/</code></td><td>1 篇总体设计和 15 篇并列模块设计，按 3 组组织</td></tr><tr><td><code>docs/delivery/</code></td><td>六个阶段、24 个小阶段和交付总览</td></tr><tr><td><code>docs/reference/</code></td><td>工程、风险、决策、边界、术语、清单和维护资料</td></tr><tr><td><code>docs/en/</code></td><td>所有页面的英文镜像</td></tr><tr><td><code>docs/.vitepress/</code></td><td>站点配置、导航、侧栏和主题</td></tr><tr><td><code>scripts/</code></td><td>交付页面生成和覆盖检查</td></tr></tbody></table><p>本地开发需要 Node.js 22.13 或更新版本以及 npm。安装依赖运行 <code>npm ci</code>，开发预览运行 <code>npm run docs:dev</code>，构建运行 <code>npm run docs:build</code>，预览构建结果运行 <code>npm run docs:preview</code>。构建产物写入 <code>docs/.vitepress/dist</code>，不要提交。</p><p>写作时先讲结论，再讲原因；一个段落只承担一个主要意思。设计说明只写产品目标和设计取舍，不写代码路径、内部类名和实现细节。文章尽量少用二级标题，不要用三级标题拆分碎片内容；需要比较时优先用表格，需要步骤时用短列表。</p><p>使用用户能理解的统一概念。必要技术名称首次出现时解释，不做名词堆叠。区分事实、判断和待验证假设，不把计划写成已经交付的能力。中文和英文保持相同路径、相同标题层级和相近内容，不新增只存在于一侧的页面。修改设计或交付结论时，同时检查相关附录、导航、侧栏和交叉链接。</p><p>开发日志每天只有一个页面：一段当天概述，加上提交、作者和具体修改。同一天有新提交就追加表格行，不恢复日志首页、模板或阶段汇报。</p><h2 id="提交检查与文档事实源" tabindex="-1">提交检查与文档事实源 <a class="header-anchor" href="#提交检查与文档事实源" aria-label="Permalink to &quot;提交检查与文档事实源&quot;">​</a></h2><p>提交前至少完成以下检查：</p><ol><li>运行 <code>npm run docs:build</code>，确认没有构建错误和站内死链。</li><li>检查中文与英文路径是否对应，侧栏和语言切换是否可达。</li><li>检查设计说明没有代码块、代码路径和无意义小标题。</li><li>如果修改事实、权限、风险或阶段目标，同步更新相关决策和附录。</li><li>不提交构建产物、缓存、本地密钥、真实用户数据或无证据的完成声明。</li></ol><p>提交说明应写清楚改了什么、为什么改、影响哪些读者或阶段，以及还需要什么证据才能确认完成。</p><p><code>docs/</code> 是仓库和文档站共同使用的唯一正式文档源。没有第二份长文副本，也没有“归档版”与线上版同时维护。中文页面先改，英文镜像在同一次提交中跟上；发现翻译或链接问题，应直接修正源文件。</p><p>项目使用 Apache-2.0 许可证。提交贡献即表示同意按该许可证发布内容。</p>',15)])])}const _=t(c,[["render",a]]);export{u as __pageData,_ as default};
